from fractions import Fraction
from collections import deque

def get_neighbors(r):
    neighbors = []
    # r + r' = 0 => r' = -r
    r_prime = -r
    if r_prime != r:
        neighbors.append(r_prime)
    # r + r' = 1 => r' = 1 - r
    r_prime = 1 - r
    if r_prime != r:
        neighbors.append(r_prime)
    # rr' = 1 => r' = 1/r
    if r != 0:
        r_prime = 1 / r
        if r_prime != r:
            neighbors.append(r_prime)
    return neighbors

def solve():
    start_node = Fraction(11, 3)
    targets = [Fraction(7, 3), Fraction(11, 4), Fraction(2024, 5), 
               Fraction(109, 11), Fraction(3, 71), Fraction(5, 204)]

    colors = {start_node: 1}
    queue = deque([start_node])

    visited_count = 0
    while queue:
        u = queue.popleft()
        visited_count += 1

        for v in get_neighbors(u):
            if v not in colors:
                colors[v] = 1 - colors[u]
                queue.append(v)
            else:
                if colors[v] != 1 - colors[u]:
                    print(f"Conflict at {v} and {u}!")
                    return None

        # Optimization: check if all targets are found
        if all(t in colors for t in targets):
            break

    return colors

