from fractions import Fraction
from collections import deque

def get_neighbors(r):
    neighbors = []
    r_prime = -r
    if r_prime != r:
        neighbors.append(r_prime)
    r_prime = 1 - r
    if r_prime != r:
        neighbors.append(r_prime)
    if r != 0:
        r_prime = 1 / r
        if r_prime != r:
            neighbors.append(r_prime)
    return neighbors

def find_path(start, end):
    queue = deque([(start, 0)])
    visited = {start: 0}
    parent = {start: None}

    while queue:
        u, dist = queue.popleft()
        if u == end:
            path = []
            while u is not None:
                path.append(u)
                u = parent[u]
            return path[::-1]

        if dist > 1000: # Limit search depth
            continue

        for v in get_neighbors(u):
            if v not in visited:
                visited[v] = dist + 1
                parent[v] = u
                queue.append((v, dist + 1))
    return None

